// Apple — Credit an App Store Purchase — For the iOS app. Send the StoreKit 2 `Transaction.jwsRepresentation` of a credit pack bought with `appAccountToken` set to `iap_account_token` from `GET /me`. It is verified against Apple's root certificate and credited once per transaction — safe to retry; finish the StoreKit transaction only after a 200. Test (sandbox) purchases are accepted only for allowlisted accounts. Errors: `INVALID_PURCHASE`, `UNKNOWN_PRODUCT`, `PURCHASE_REVOKED`, `ACCOUNT_MISMATCH`, `SANDBOX_NOT_ALLOWED`.
func (s *TopupsService) Apple(ctx context.Context, params CreateAppleTopupParams, opts ...RequestOption) (*IapTopupResult, error) {
	req := apiRequest{method: http.MethodPost, path: "/topups/apple"}
	req.body = params
	out := new(IapTopupResult)
	if err := s.t.do(ctx, req, out, opts...); err != nil {
		return nil, err
	}
	return out, nil
}

// Google — Credit a Google Play Purchase — For the Android app. Send the product id and purchase token of a credit pack bought with `obfuscatedAccountId` set to `iap_account_token` from `GET /me`. Checked with Google Play, credited once per order and consumed — safe to retry. Errors as for Apple, plus `PURCHASE_PENDING` and `IAP_UNAVAILABLE`.
func (s *TopupsService) Google(ctx context.Context, params CreateGoogleTopupParams, opts ...RequestOption) (*IapTopupResult, error) {
	req := apiRequest{method: http.MethodPost, path: "/topups/google"}
	req.body = params
	out := new(IapTopupResult)
	if err := s.t.do(ctx, req, out, opts...); err != nil {
		return nil, err
	}
	return out, nil
}

// EventsService: Live account events.
type EventsService struct{ t *transport }

// Poll — Live Events (Server-Sent Events) — A `text/event-stream` of your account's events — `activation.code_received`, `activation.sms_received`, `activation.expired` (refunded), `activation.canceled`, `activation.finished`, `rental.sms_received`, `rental.expired`, `topup.completed`, `reminder.back_in_stock`. Each connection lasts ~55 s; reconnect with `Last-Event-ID` (EventSource does this for you) and nothing is missed — the last 200 events are kept for 7 days. `?once=1` returns pending events as JSON instead, for clients that would rather poll.
func (s *EventsService) Poll(ctx context.Context, params *StreamEventsParams, opts ...RequestOption) (*EventPoll, error) {
	req := apiRequest{method: http.MethodGet, path: "/events"}
	req.query = params.values()
	if req.query == nil {
		req.query = url.Values{}
	}
	req.query.Set("once", "1")
	out := new(EventPoll)
	if err := s.t.do(ctx, req, out, opts...); err != nil {
		return nil, err
	}
	return out, nil
}

