func newServices(t *transport) services {
	return services{
		Services:       &ServicesService{t},
		Countries:      &CountriesService{t},
		Prices:         &PricesService{t},
		Activations:    &ActivationsService{t},
		Rentals:        &RentalsService{t},
		Account:        &AccountService{t},
		Reminders:      &RemindersService{t},
		ApiKeys:        &ApiKeysService{t},
		Webhook:        &WebhookService{t},
		Sessions:       &SessionsService{t},
		Topups:         &TopupsService{t},
		Events:         &EventsService{t},
		Devices:        &DevicesService{t},
		Auth:           &AuthService{t},
		Reseller:       &ResellerService{t},
		ResellerPublic: &ResellerPublicService{t},
	}
}

// services are the generated API resources, embedded in Client.
type services struct {
	Services       *ServicesService       // Find services (the sites and apps you can receive codes for).
	Countries      *CountriesService      // Countries numbers are available in.
	Prices         *PricesService         // Live prices, stock and success rates.
	Activations    *ActivationsService    // One-time numbers: buy, wait for the code, finish, cancel.
	Rentals        *RentalsService        // Rented numbers that receive SMS for hours or days.
	Account        *AccountService        // Your account, balance and transactions.
	Reminders      *RemindersService      // Back-in-stock reminders.
	ApiKeys        *ApiKeysService        // Developer API keys (needs a signed-in person, not an API key).
	Webhook        *WebhookService        // Your webhook URL and signing secret.
	Sessions       *SessionsService       // Signed-in apps, extensions, CLIs and agents.
	Topups         *TopupsService         // Add balance by card or crypto.
	Events         *EventsService         // Live account events.
	Devices        *DevicesService        // Push notification registration (apps and extensions).
	Auth           *AuthService           // Sign-in and tokens.
	Reseller       *ResellerService       // Reseller management (reseller accounts only).
	ResellerPublic *ResellerPublicService // A reseller's white-label sign-up and top-up.
}
